export interface RedisClient {
  get(key: string): Promise<string | null>;
  set(key: string, value: string, mode: "EX", ttl: number): Promise<"OK">;
  del(key: string): Promise<number>;
}

export interface FareQuote {
  routeKey: string;
  carrier: string;
  cabin: "economy" | "premium" | "business";
  totalMinor: number;
  currency: string;
  quotedAt: number;
  validUntil: number;
}

export interface FareSupplier {
  quote(origin: string, dest: string, date: string, cabin: FareQuote["cabin"]): Promise<FareQuote>;
}

import { FareQuote, FareSupplier, RedisClient } from "./types";

const DEFAULT_TTL_MS = 5 * 60 * 1000;
const MIN_TTL_MS = 15 * 1000;

export class FareQuoteCache {
  constructor(
    private readonly redis: RedisClient,
    private readonly supplier: FareSupplier,
    private readonly now: () => number = Date.now,
  ) {}

  private key(origin: string, dest: string, date: string, cabin: string): string {
    return `fare:v2:${origin}:${dest}:${date}:${cabin}`;
  }

  async getQuote(
    origin: string,
    dest: string,
    date: string,
    cabin: FareQuote["cabin"],
  ): Promise<FareQuote> {
    const key = this.key(origin, dest, date, cabin);
    const raw = await this.redis.get(key);
    if (raw) {
      const cached = JSON.parse(raw) as FareQuote;
      if (cached.validUntil > this.now()) {
        return cached;
      }
      await this.redis.del(key);
    }

    const fresh = await this.supplier.quote(origin, dest, date, cabin);
    const ttlMs = this.ttlFor(fresh);
    if (ttlMs > 0) {
      await this.redis.set(key, JSON.stringify(fresh), "EX", ttlMs);
    }
    return fresh;
  }

  private ttlFor(quote: FareQuote): number {
    const remaining = quote.validUntil - this.now();
    if (remaining <= MIN_TTL_MS) {
      return 0;
    }
    return Math.min(remaining, DEFAULT_TTL_MS);
  }
}

import { FareQuoteCache } from "./fareQuoteCache";
import { FareQuote } from "./types";

export interface PriceCheckResult {
  ok: boolean;
  quote: FareQuote;
  reason?: string;
}

export class BookingPriceCheck {
  constructor(private readonly cache: FareQuoteCache) {}

  async confirmPrice(
    origin: string,
    dest: string,
    date: string,
    cabin: FareQuote["cabin"],
    displayedMinor: number,
  ): Promise<PriceCheckResult> {
    const quote = await this.cache.getQuote(origin, dest, date, cabin);
    if (quote.totalMinor !== displayedMinor) {
      return { ok: false, quote, reason: "PRICE_CHANGED" };
    }
    return { ok: true, quote };
  }
}
